SELECT database,name,engine,total_rows,total_bytes,sorting_key,primary_key,partition_key FROM system.tables WHERE (database='quotes_async_t4' AND name IN ('quotes','quotes_daily')) OR (database='system' AND startsWith(name,'query_log')) ORDER BY database,name LIMIT 20 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames